{"command":"$script = @'
$ErrorActionPreference = 'Stop'
$stdout = Join-Path (Get-Location) '.tura-dev-hydration.out.log'
$stderr = Join-Path (Get-Location) '.tura-dev-hydration.err.log'
if (Test-Path $stdout) { Remove-Item $stdout }
if (Test-Path $stderr) { Remove-Item $stderr }
$p = Start-Process -FilePath 'npm.cmd' -ArgumentList @('run','dev','--','--port','3011') -WorkingDirectory (Get-Location) -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru -WindowStyle Hidden
try {
  $ready = $false
  for ($i=0; $i -lt 40; $i++) {
    if ($p.HasExited) { throw "server exited $($p.ExitCode) $(Get-Content $stderr -Raw -ErrorAction SilentlyContinue)" }
    try { $r = Invoke-WebRequest -Uri 'http://127.0.0.1:3011/' -UseBasicParsing -TimeoutSec 1; if ($r.StatusCode -eq 200) { $ready = $true; break } } catch {}
    Start-Sleep -Milliseconds 500
  }
  if (-not $ready) { throw 'server not ready' }
  $node = @'NODE'
import { chromium } from '@playwright/test';
const browser = await chromium.launch();
const page = await browser.newPage();
page.on('console', msg => console.log('CONSOLE', msg.type(), msg.text()));
page.on('pageerror', err => console.log('PAGEERROR', err.message));
await page.goto('http://127.0.0.1:3011/', { waitUntil: 'networkidle' });
console.log('body', (await page.locator('body').innerText()).slice(0,120));
console.log('saveButtons', await page.getByRole('button', { name: 'Save' }).count());
const tile = page.locator('.tile').nth(1);
await tile.hover();
await tile.getByRole('button', { name: 'Save' }).click({ force: true });
await page.waitForTimeout(500);
console.log('status', await page.getByRole('status').innerText());
await browser.close();
NODE
  Set-Content -Path '.tura-hydration-check.mjs' -Value $node
  node .tura-hydration-check.mjs
} finally {
  if (-not $p.HasExited) { Stop-Process -Id $p.Id -Force }
}
